<?php
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../includes/master_data_helper.php';$groups=master_groups();$group=$_GET['group']??$_POST['group']??'';if(!isset($groups[$group]))redirect('pages/master/index.php');$meta=$groups[$group];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if(in_array($action,['create','update'],true)){$name=trim($_POST['item_name']??'');$code=strtolower(trim($_POST['item_code']??''));$code=preg_replace('/[^a-z0-9]+/','_',$code?:$name);$code=trim($code,'_');if($name===''||$code==='')throw new RuntimeException('Nama master wajib diisi.');$check=$pdo->prepare("SELECT id FROM master_data_items WHERE group_code=:group AND (item_code=:code OR LOWER(item_name)=LOWER(:name)) AND id<>:id LIMIT 1");$check->execute([':group'=>$group,':code'=>$code,':name'=>$name,':id'=>$id]);if($check->fetch())throw new RuntimeException('Kode atau nama sudah digunakan pada kelompok ini.');if($action==='create')$pdo->prepare("INSERT INTO master_data_items(group_code,item_code,item_name,description,created_by) VALUES(:group,:code,:name,:description,:user)")->execute([':group'=>$group,':code'=>$code,':name'=>$name,':description'=>trim($_POST['description']??''),':user'=>$_SESSION['user_id']??null]);else $pdo->prepare("UPDATE master_data_items SET item_code=:code,item_name=:name,description=:description WHERE id=:id AND group_code=:group")->execute([':code'=>$code,':name'=>$name,':description'=>trim($_POST['description']??''),':id'=>$id,':group'=>$group]);}elseif($action==='toggle')$pdo->prepare("UPDATE master_data_items SET status=IF(status='active','inactive','active') WHERE id=:id AND group_code=:group")->execute([':id'=>$id,':group'=>$group]);elseif($action==='delete')$pdo->prepare("DELETE FROM master_data_items WHERE id=:id AND group_code=:group AND is_system=0")->execute([':id'=>$id,':group'=>$group]);redirect('pages/master/items.php?group='.$group.'&saved=1');}catch(Throwable $e){$error=$e->getMessage();}}
$items=master_group($pdo,$group,false);$pageTitle=$meta[0].' - Master Data';require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';?>
<main class="main-content"><div class="page-header d-flex justify-content-between align-items-center flex-wrap gap-3"><div><a class="small text-success text-decoration-none" href="<?=base_url('pages/master/index.php');?>">← Master Data</a><h1 class="fw-bold mb-1"><?=htmlspecialchars($meta[0]);?></h1><p class="text-muted mb-0">Kelola referensi <?=strtolower(htmlspecialchars($meta[0]));?> Nukari.</p></div><button class="btn btn-nukari" data-bs-toggle="modal" data-bs-target="#itemModal"><i class="bi bi-plus-circle me-1"></i> Tambah</button></div><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error);?></div><?php endif;?><?php if(!empty($_GET['saved'])):?><div class="alert alert-success py-2">Master data berhasil diperbarui.</div><?php endif;?><div class="panel"><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Kode</th><th>Nama</th><th>Keterangan</th><th>Status</th><th class="text-end">Aksi</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><code><?=htmlspecialchars($item['item_code']);?></code></td><td><b><?=htmlspecialchars($item['item_name']);?></b><?=$item['is_system']?'<br><small class="text-muted">Default Nukari</small>':'';?></td><td><?=htmlspecialchars($item['description']?:'-');?></td><td><?=$item['status']==='active'?'<span class="badge bg-success">Aktif</span>':'<span class="badge bg-secondary">Nonaktif</span>';?></td><td class="text-end"><button class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#itemModal" data-item='<?=htmlspecialchars(json_encode($item),ENT_QUOTES,'UTF-8');?>'>Edit</button> <form method="POST" class="d-inline"><?=csrf_field();?><input type="hidden" name="group" value="<?=htmlspecialchars($group);?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$item['id'];?>"><button class="btn btn-sm btn-outline-secondary"><?=$item['status']==='active'?'Nonaktifkan':'Aktifkan';?></button></form><?php if(!$item['is_system']):?> <form method="POST" class="d-inline" onsubmit="return confirm('Hapus data ini?')"><?=csrf_field();?><input type="hidden" name="group" value="<?=htmlspecialchars($group);?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$item['id'];?>"><button class="btn btn-sm btn-outline-danger">Hapus</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></main>
<div class="modal fade" id="itemModal"><div class="modal-dialog modal-dialog-centered"><form method="POST" class="modal-content rounded-4 border-0"><?=csrf_field();?><input type="hidden" name="group" value="<?=htmlspecialchars($group);?>"><input type="hidden" name="action" id="itemAction" value="create"><input type="hidden" name="id" id="itemId"><div class="modal-header"><h5 class="fw-bold mb-0" id="itemTitle">Tambah <?=htmlspecialchars($meta[0]);?></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body row g-3"><div class="col-12"><label class="form-label">Nama</label><input name="item_name" id="itemName" class="form-control" required></div><div class="col-12"><label class="form-label">Kode</label><input name="item_code" id="itemCode" class="form-control" placeholder="Dibuat otomatis dari nama"></div><div class="col-12"><label class="form-label">Keterangan</label><textarea name="description" id="itemDescription" class="form-control"></textarea></div></div><div class="modal-footer"><button class="btn btn-light" data-bs-dismiss="modal">Batal</button><button class="btn btn-nukari">Simpan</button></div></form></div></div><script>document.getElementById('itemModal')?.addEventListener('show.bs.modal',e=>{const i=e.relatedTarget?.dataset.item?JSON.parse(e.relatedTarget.dataset.item):null;document.getElementById('itemAction').value=i?'update':'create';document.getElementById('itemId').value=i?.id||'';document.getElementById('itemName').value=i?.item_name||'';document.getElementById('itemCode').value=i?.item_code||'';document.getElementById('itemDescription').value=i?.description||'';});</script><?php require_once __DIR__.'/../../includes/footer.php';?>
